typedef CGAL::Polygon_2<Kernel>                           CGALPolygon;
typedef CGAL::Polygon_with_holes_2<Kernel>                CGALPolygonWithHoles;

auto toCGALPolygon = [](const Polygon2d& p) {
    CGALPolygon poly;
    for (const cg3::Point2d& pt : p) {
        poly.push_back(Point_2(pt.x(), pt.y()));
    }
    return poly;
