auto toCGALPolygonWithHoles = [](const CGALPolygonWithHoles& pwh) {
    PolygonWithHoles2d result;
    result.outerPolygon.clear();
    for (auto it = pwh.outer_boundary().vertices_begin(); it != pwh.outer_boundary().vertices_end(); ++it) {
        result.outerPolygon.pushBack(cg3::Point2d(CGAL::to_double(it->x()), CGAL::to_double(it->y())));
    }
    for (auto hit = pwh.holes_begin(); hit != pwh.holes_end(); ++hit) {
        Polygon2d hole;
        for (auto vit = hit->vertices_begin(); vit != hit->vertices_end(); ++vit) {
            hole.pushBack(cg3::Point2d(CGAL::to_double(vit->x()), CGAL::to_double(vit->y())));
        }
        result.holes.push_back(hole);
    }
    return result;
};

